-- Inventory projection for future trusted sync; no browser writes or live sync enabled.
alter table public.items add column sku text not null default '';
alter table public.items add column category text not null default '';
alter table public.items add column brand text not null default '';
alter table public.items add column item_kind text not null default 'product' check(item_kind in ('product','service'));
alter table public.items add column base_unit text not null default 'قطعة';
alter table public.items add column unit_code text not null default 'PCE';
alter table public.items add column track_stock boolean not null default false;
alter table public.items add column reorder_micro bigint not null default 0 check(reorder_micro>=0);
alter table public.items add column purchase_cost bigint not null default 0 check(purchase_cost>=0);
alter table public.items add column weight_kg text not null default '';
alter table public.items add column volume_l text not null default '';
alter table public.items add column length_cm text not null default '';
alter table public.items add column width_cm text not null default '';
alter table public.items add column height_cm text not null default '';
alter table public.items add column size_label text not null default '';
alter table public.items add column color text not null default '';
alter table public.items add column notes text not null default '';
create unique index items_sku_unique on public.items(organization_id,installation_id,sku) where sku<>'';
create table public.warehouses(id uuid primary key default gen_random_uuid(),organization_id uuid not null,installation_id uuid not null,local_id bigint not null,name text not null,active boolean not null default true,unique(organization_id,id),unique(organization_id,installation_id,local_id),unique(organization_id,installation_id,name),foreign key(organization_id,installation_id) references public.installations(organization_id,id));
alter table public.pos_points add column warehouse_id uuid;
alter table public.pos_points add foreign key(organization_id,warehouse_id) references public.warehouses(organization_id,id);
create table public.item_units(id uuid primary key default gen_random_uuid(),organization_id uuid not null,installation_id uuid not null,local_id bigint not null,item_id uuid not null,name text not null,unit_code text not null default 'PCE',factor_micro bigint not null check(factor_micro>0 and factor_micro<=1000000000000),unit_price bigint not null check(unit_price>=0),barcode text,active boolean not null default true,unique(organization_id,id),unique(organization_id,installation_id,local_id),unique(organization_id,item_id,name),foreign key(organization_id,installation_id) references public.installations(organization_id,id),foreign key(organization_id,item_id) references public.items(organization_id,id));
create unique index item_units_barcode_unique on public.item_units(organization_id,barcode) where barcode is not null;
alter table public.invoice_lines add column item_id uuid;
alter table public.invoice_lines add foreign key(organization_id,item_id) references public.items(organization_id,id);
alter table public.invoice_lines add column stock_qty_micro bigint not null default 0 check(stock_qty_micro>=0);
alter table public.invoice_lines add column unit_factor_micro bigint not null default 1000000;
alter table public.invoice_lines add column unit_name text not null default '';
alter table public.invoice_lines add column warehouse_id uuid;
alter table public.invoice_lines add foreign key(organization_id,warehouse_id) references public.warehouses(organization_id,id);
create table public.stock_movements(id uuid primary key default gen_random_uuid(),organization_id uuid not null,installation_id uuid not null,local_id bigint not null,event_id text not null,request_hash text not null,item_id uuid not null,warehouse_id uuid not null,delta_micro bigint not null check(delta_micro<>0 and abs(delta_micro)<=9007199254740991),kind text not null check(kind in ('opening','receipt','issue','adjust_in','adjust_out','transfer_in','transfer_out','sale','return')),invoice_id uuid,line_no integer,reason text not null,local_actor_id bigint,created_at timestamptz not null,unique(organization_id,id),unique(organization_id,installation_id,local_id),unique(organization_id,installation_id,event_id,warehouse_id,item_id),foreign key(organization_id,installation_id) references public.installations(organization_id,id),foreign key(organization_id,item_id) references public.items(organization_id,id),foreign key(organization_id,warehouse_id) references public.warehouses(organization_id,id),foreign key(organization_id,invoice_id,line_no) references public.invoice_lines(organization_id,invoice_id,line_no));
create unique index stock_movement_invoice_line on public.stock_movements(organization_id,invoice_id,line_no) where invoice_id is not null;
create unique index stock_opening_once on public.stock_movements(organization_id,item_id,warehouse_id) where kind='opening';
create trigger stock_movements_immutable before update or delete on public.stock_movements for each row execute function private.reject_ledger_edit();
alter table public.warehouses enable row level security;
revoke all on public.warehouses from anon,authenticated;
grant select on public.warehouses to authenticated;
grant all on public.warehouses to service_role;
create policy warehouses_managers on public.warehouses for select to authenticated using(private.has_org_role(organization_id,array['owner','accountant']));
alter table public.item_units enable row level security;
revoke all on public.item_units from anon,authenticated;
grant select on public.item_units to authenticated;
grant all on public.item_units to service_role;
create policy item_units_managers on public.item_units for select to authenticated using(private.has_org_role(organization_id,array['owner','accountant']));
alter table public.stock_movements enable row level security;
revoke all on public.stock_movements from anon,authenticated;
grant select on public.stock_movements to authenticated;
grant all on public.stock_movements to service_role;
create policy stock_movements_managers on public.stock_movements for select to authenticated using(private.has_org_role(organization_id,array['owner','accountant']));
